import * as THREE from './three.module.js';
import {COURT as C,wallX} from './court-geometry.js';
import {block,beam,finish} from './venue-tools.js';
import {mainWallRuns,wallFrame,mainWallSurface,venueRear} from './venue-walls.js';
function windowGlass(){if(typeof document==='undefined')return null;const canvas=document.createElement('canvas');canvas.width=128;canvas.height=256;const c=canvas.getContext('2d'),sky=c.createLinearGradient(0,0,0,256);sky.addColorStop(0,'#637e87');sky.addColorStop(.6,'#a1b4b1');sky.addColorStop(1,'#586b65');c.fillStyle=sky;c.fillRect(0,0,128,256);c.strokeStyle='#3d535344';c.lineWidth=4;for(let x=8;x<128;x+=38){c.beginPath();c.moveTo(x,256);c.lineTo(x+12,120);c.stroke();}c.fillStyle='#dae7d215';c.beginPath();c.moveTo(0,0);c.lineTo(45,0);c.lineTo(128,160);c.lineTo(128,235);c.fill();const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;return t;}
export function buildPalestraHall(){
 const sides=new THREE.Group(),ends=[],rafters=[],upperWalls=new THREE.Group(),navy=finish('#233d56'),red=finish('#9e3541'),plaster=finish('#c5b59e'),sill=finish('#9c9584'),steel=finish('#354950',{metalness:.25}),glass=new THREE.MeshBasicMaterial({color:'#ffffff',map:windowGlass(),side:THREE.DoubleSide}),lamp=new THREE.MeshBasicMaterial({color:'#f5dfb4'});sides.userData.palestraHall=true;sides.add(upperWalls);
 function arch(x,bottom,spring,r){const shape=new THREE.Shape();shape.moveTo(x-r,bottom);shape.lineTo(x+r,bottom);shape.lineTo(x+r,spring);shape.absarc(x,spring,r,0,Math.PI,false);shape.lineTo(x-r,bottom);shape.closePath();return shape;}
 function panel(span){const g=new THREE.Group(),outer=new THREE.Shape();outer.moveTo(-span/2,3.4);outer.lineTo(span/2,3.4);outer.lineTo(span/2,8.25);outer.lineTo(-span/2,8.25);outer.closePath();const count=span<2.7?0:Math.max(1,Math.floor(span/3.25)),step=span/Math.max(1,count);for(let i=0;i<count;i++){const x=-span/2+(i+.5)*step,r=Math.min(.67,step*.26),bottom=5.0,spring=6.85,hole=arch(x,bottom,spring,r);outer.holes.push(new THREE.Path(hole.getPoints(24).reverse()));
  const pane=new THREE.Mesh(new THREE.ShapeGeometry(arch(x,bottom,spring,r),20),glass);pane.position.z=-.15;const pos=pane.geometry.attributes.position,uv=pane.geometry.attributes.uv;for(let j=0;j<uv.count;j++)uv.setXY(j,(pos.getX(j)-x+r)/(2*r),(pos.getY(j)-bottom)/(spring+r-bottom));pane.userData.recessedWindow=true;pane.userData.recessDepth=.15;g.add(pane);
  for(const dx of [-r,r]){block(g,.055,spring-bottom,.25,x+dx,(bottom+spring)/2,-.065,steel);block(g,.10,spring-bottom,.28,x+dx+Math.sign(dx)*.06,(bottom+spring)/2,-.11,sill);}for(let a=0;a<Math.PI;a+=Math.PI/16){const b=a+Math.PI/16;beam(g,[x+Math.cos(a)*r,spring+Math.sin(a)*r,.016],[x+Math.cos(b)*r,spring+Math.sin(b)*r,.016],.035,steel);}
  beam(g,[x,bottom,-.025],[x,spring+r,-.025],.018,steel);for(const y of [5.65,6.30,6.85])beam(g,[x-r,y,-.025],[x+r,y,-.025],.018,steel);block(g,2*r+.23,.13,.43,x,bottom-.07,-.04,sill);
 }
 const geo=new THREE.ExtrudeGeometry(outer,{depth:.22,steps:1,bevelEnabled:false,curveSegments:18});geo.translate(0,0,-.22);const wall=new THREE.Mesh(geo,plaster);wall.userData.windowedWall=true;wall.receiveShadow=true;g.add(wall);
 // Navy wainscoting and fine red bands are part of the architecture itself.
 block(g,span,.72,.055,0,3.76,.034,navy);block(g,span,.115,.07,0,4.19,.042,red);block(g,span,.10,.07,0,8.21,.04,navy);return g;}
 const runs=mainWallRuns();for(const run of runs){const frame=wallFrame(run);frame.add(panel(Math.hypot(run.xb-run.xa,run.b-run.a)));upperWalls.add(frame);for(const [low,high,mat]of [[3.16,3.36,navy]])mainWallSurface(sides,run,low,high,mat);}
 const left=panel(venueRear+C.halfLength);left.position.set(C.roofOuterX,0,(venueRear-C.halfLength)/2);left.rotation.y=Math.PI/2;upperWalls.add(left);
 for(const side of [-1,1]){const g=new THREE.Group(),z=side>0?venueRear:-C.halfLength,right=wallX(z),span=right-C.roofOuterX;g.userData.endSide=side;const face=panel(span);face.position.set((right+C.roofOuterX)/2,0,z);face.rotation.y=side>0?Math.PI:0;g.add(face);ends.push(g);}
 // The far-half arched roof structure frames the court without hiding play.
 for(let z=-13;z<venueRear;z+=4.5){const g=new THREE.Group();g.userData.trussZ=z;rafters.push(g);sides.add(g);for(let i=0;i<18;i++){const x=-7.2+i*12.5/18,xx=x+12.5/18,top=X=>8.35+3.1*Math.sqrt(Math.max(0,1-((X+1)/6.3)**2));beam(g,[x,top(x),z],[xx,top(xx),z],.065,steel);beam(g,[x,top(x)-.43,z],[xx,top(xx)-.43,z],.038,steel);beam(g,[x,top(x)-.43,z],[xx,top(xx),z],.022,steel);}for(const x of [-4,1.9]){beam(g,[x,10.1,z],[x,8.5,z],.014,steel);block(g,.58,.06,.30,x,8.48,z,lamp);}}
 let active=false,overview=false;return {sides,ends,setVisible(on,over=false){active=on;overview=over;sides.visible=on;upperWalls.visible=!over;for(const g of ends)g.visible=on&&!over;},setEndView(side){for(const g of rafters)g.visible=active&&!overview&&g.userData.trussZ*side<2;},update(){}};
}
